package store

import (
	"time"

	"github.com/google/uuid"

	"github.com/lukerops/mserver/internal/modules/storage/driver"
)

// Records are identified by UUIDv7.

// Location is a directory registered by the operator and accessed through
// a driver. Locations never overlap, so every file belongs to exactly one
// location.
type Location struct {
	ID     uuid.UUID
	Driver string
	// Options are driver specific (e.g. "dir" for the local driver).
	Options   map[string]string
	CreatedAt time.Time
}

// File is an indexed file. Its ID is generated by the storage on first
// indexing and is the only way other modules refer to files.
type File struct {
	ID         uuid.UUID
	LocationID uuid.UUID
	// Path is slash-separated and relative to the location.
	Path    string
	Size    int64
	ModTime time.Time
	// Inode is zero when the driver does not support inodes.
	Inode uint64
}

// Sibling is a file in the same directory as another one.
type Sibling struct {
	FileID uuid.UUID
	// Path is relative to the location.
	Path string
}

// ScanChanges is the difference between the index and a location walk.
type ScanChanges struct {
	Added   map[uuid.UUID]driver.FileInfo
	Updated map[uuid.UUID]driver.FileInfo // changed or moved
	Removed []uuid.UUID
}
